mapper.select:
		select * from (
			select u.user_id,u.user_name,u.password_update_date,u.user_type,u.user_relation_id,u.disable_deadline_date,u.disable_state,
			u.create_by,u.create_date,u.last_update_by,u.last_update_date,ifnull(tl.full_name, u.user_description) user_description
			from sys_user u

                join sys_user_role ur on ur.user_id = u.user_id and ur.role_id = #{roleId}

			left join sys_org_person_b b on b.person_id = u.user_relation_id
			left join sys_org_person_tl tl on b.person_id = tl.person_id and tl.language = 'zh-CN'

				where u.disable_state = #{disableState}

		) a


				user_name like CONCAT( CONCAT('%',#{userName} ),'%')


				${montage}


				user_description like CONCAT( CONCAT('%',#{userDescription} ),'%')

mapper.update:
