USER_NAME = #{userName}, USER_DESCRIPTION = #{userDescription},
PASSWORD = #{password}, PASSWORD_UPDATE_DATE = #{passwordUpdateDate},
USER_TYPE = #{userType}, USER_RELATION_ID = #{userRelationId}, LAST_UPDATE_BY = #{lastUpdateBy}, LAST_UPDATE_DATE = #{lastUpdateDate}, LAST_UPDATE_LOGIN = #{lastUpdateLogin}, DISABLE_STATE = #{disableState}
where user_id = #{userId}

update sys_user

    LOGIN_ERROR_COUNT = #{loginErrorCount},
    DISABLE_DEADLINE_DATE = #{disableDeadlineDate},
    DISABLE_STATE = #{disableState}

where user_id = #{userId}

